import type { Queryable } from '../../db/client';
import type { WeatherCondition, WeatherSignal } from './types';

/**
 * Weather input (optional) — SIMULATED
 * ====================================
 *
 * Weather is one of the model's inputs, so it is a first-class (optional) part
 * of the prediction. Conditions are read from the `weather_conditions` table,
 * which holds *simulated* rows generated by `supabase/seed/0005_weather.sql` —
 * a deterministic monsoon-flavoured pattern, not a real forecast feed.
 *
 * The demand multipliers below are transparent modelling assumptions for the
 * prototype (rain pushes riders onto transit, heavy disruption suppresses
 * trips). They are **not** measured effects and must not be quoted as such.
 *
 * To use a real provider later: implement `WeatherProvider` and hand it to
 * `createPredictionEngine()`. Nothing else in the pipeline changes.
 */

export interface WeatherSlot extends WeatherSignal {
  at: string;
}

export interface WeatherProvider {
  readonly id: string;
  readonly source: 'simulated' | 'external';
  /** Slots covering at least the next few hours, ordered by time. */
  list(from: Date, hours: number): Promise<WeatherSlot[]>;
}

/** Simulated demand multipliers per condition (prototype assumptions). */
export const WEATHER_FACTORS: Record<
  WeatherCondition,
  { label: string; factor: number; severity: 0 | 1 | 2 | 3 }
> = {
  clear: { label: 'Clear', factor: 1.0, severity: 0 },
  cloudy: { label: 'Cloudy', factor: 1.01, severity: 0 },
  light_rain: { label: 'Light rain', factor: 1.04, severity: 1 },
  heavy_rain: { label: 'Heavy rain', factor: 1.09, severity: 2 },
  storm: { label: 'Storm', factor: 0.92, severity: 3 },
  heatwave: { label: 'Heatwave', factor: 1.06, severity: 2 },
};

interface WeatherRow {
  city: string;
  observed_at: string | Date;
  condition: WeatherCondition;
  temperature_c: number | string | null;
  rainfall_mm: number | string | null;
  severity: number | string | null;
}

function mapSlot(row: WeatherRow): WeatherSlot {
  const profile = WEATHER_FACTORS[row.condition] ?? WEATHER_FACTORS.clear;
  return {
    at: new Date(row.observed_at).toISOString(),
    city: row.city,
    condition: row.condition,
    label: profile.label,
    factor: profile.factor,
    severity: (Number(row.severity ?? profile.severity) || profile.severity) as 0 | 1 | 2 | 3,
    temperatureC: row.temperature_c === null ? null : Number(row.temperature_c),
    rainfallMm: Number(row.rainfall_mm ?? 0),
    observedAt: new Date(row.observed_at).toISOString(),
    source: 'simulated',
  };
}

export async function listWeatherSlots(
  db: Queryable,
  options: { from?: Date; hours?: number } = {},
): Promise<WeatherSlot[]> {
  const from = options.from ?? new Date();
  const hours = options.hours ?? 12;

  let rows: WeatherRow[] = [];
  try {
    rows = await db.query<WeatherRow>(
      `select city, observed_at, condition, temperature_c, rainfall_mm, severity
         from weather_conditions
        where observed_at between $1::timestamptz - interval '1 hour'
                              and $1::timestamptz + make_interval(hours => $2::integer)
        order by observed_at`,
      [from.toISOString(), hours],
    );
  } catch {
    // Table missing or unreadable (e.g. a database created before the weather
    // migration): fall through to the synthesised pattern below so the optional
    // weather factor never breaks a prediction request.
    rows = [];
  }

  const slots = rows.map(mapSlot);
  if (slots.length >= 2) return slots;

  // No usable rows for this window — synthesise a deterministic simulated
  // pattern instead of silently dropping the weather input.
  return synthesiseSlots(from, Math.max(hours, 6));
}

/**
 * Simulated fallback slots (hourly, deterministic) used when
 * `weather_conditions` has nothing covering the requested window. Same
 * monsoon-flavoured shape as the demo seed, so the UI cannot tell the two
 * apart — both are explicitly labelled simulated.
 */
function synthesiseSlots(from: Date, hours: number): WeatherSlot[] {
  const start = new Date(from);
  start.setMinutes(0, 0, 0);
  const slots: WeatherSlot[] = [];
  for (let offset = 0; offset <= hours; offset += 1) {
    const at = new Date(start.getTime() + offset * 60 * 60 * 1000);
    const localHour = Number(
      new Intl.DateTimeFormat('en-GB', { hour: '2-digit', hour12: false, timeZone: 'Asia/Kolkata' })
        .format(at),
    );
    const phase = hash(`${at.toISOString().slice(0, 13)}`);
    const condition: WeatherCondition =
      phase < 0.05 && localHour >= 15 && localHour <= 20
        ? 'storm'
        : phase < 0.14
          ? 'heavy_rain'
          : phase < 0.3
            ? 'light_rain'
            : phase < 0.52
              ? 'cloudy'
              : phase > 0.95 && localHour >= 12 && localHour <= 15
                ? 'heatwave'
                : 'clear';
    slots.push({ ...synthesiseWeather(condition, at), at: at.toISOString() });
  }
  return slots;
}

/** Stable 0..1 pseudo-random value for a string key (no Math.random). */
function hash(key: string): number {
  let value = 0x811c9dc5;
  for (let i = 0; i < key.length; i += 1) {
    value ^= key.charCodeAt(i);
    value = Math.imul(value, 0x01000193);
  }
  return ((value >>> 0) % 100000) / 100000;
}

/** Most recent simulated observation at or before `at` (falls back to latest). */
export async function currentWeather(
  db: Queryable,
  at: Date = new Date(),
): Promise<WeatherSlot | null> {
  const rows = await db.query<WeatherRow>(
    `select city, observed_at, condition, temperature_c, rainfall_mm, severity
       from weather_conditions
      where observed_at <= $1::timestamptz
      order by observed_at desc
      limit 1`,
    [at.toISOString()],
  );
  return rows.length ? mapSlot(rows[0]) : null;
}

/** Slot closest to the target instant (the engine predicts up to 2h ahead). */
export function nearestWeather(slots: WeatherSlot[], at: Date): WeatherSlot | null {
  if (!slots.length) return null;
  let best = slots[0];
  let bestDistance = Math.abs(new Date(best.at).getTime() - at.getTime());
  for (const slot of slots) {
    const distance = Math.abs(new Date(slot.at).getTime() - at.getTime());
    if (distance < bestDistance) {
      best = slot;
      bestDistance = distance;
    }
  }
  // Ignore slots more than 3 hours from the target — stale weather is noise.
  return bestDistance <= 3 * 60 * 60 * 1000 ? best : null;
}

/**
 * Build a weather signal for a scenario override (used by the Prediction Engine
 * screen's "what if it rains?" control). No database access involved.
 */
export function synthesiseWeather(
  condition: WeatherCondition,
  at: Date = new Date(),
  city = 'Chennai (simulated)',
): WeatherSignal {
  const profile = WEATHER_FACTORS[condition] ?? WEATHER_FACTORS.clear;
  return {
    condition,
    label: profile.label,
    factor: profile.factor,
    severity: profile.severity,
    temperatureC: condition === 'heatwave' ? 41 : condition === 'storm' ? 27 : 31,
    rainfallMm: condition === 'heavy_rain' ? 12.4 : condition === 'light_rain' ? 2.1 : 0,
    city,
    observedAt: at.toISOString(),
    source: 'simulated',
  };
}

export const WEATHER_CONDITIONS = Object.keys(WEATHER_FACTORS) as WeatherCondition[];

export function isWeatherCondition(value: string): value is WeatherCondition {
  return (WEATHER_CONDITIONS as string[]).includes(value);
}
